#include <stdint.h>
#include <stdio.h>
#include "main.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

RCC_AHB1ENR_t volatile *pRCCRegister;
GPIOx_MODE_t volatile *pGpioDModeRegister;
GPIOx_ODR_t volatile *pGpioDOutputRegister;
GPIOx_IDR_t volatile *pGpioDInputRegister;
GPIOx_PUPDR_t volatile *pGpioDPullRegister;

void Inintialize();
void DelayDevice();
void CheckRow(int row);

int main(void)
{
	pRCCRegister = (RCC_AHB1ENR_t*)0x40023830;
	pGpioDModeRegister = (GPIOx_MODE_t*)0x40020C00;
	pGpioDOutputRegister = (GPIOx_ODR_t*)0x40020C14;
	pGpioDInputRegister = (GPIOx_IDR_t*)0x40020C10;
	pGpioDPullRegister = (GPIOx_PUPDR_t*)0x40020C0C;

	Inintialize();

	while(1)
	{
		pGpioDOutputRegister->odr_0 = 0;

		CheckRow(0);

		pGpioDOutputRegister->odr_0 = 1;
		pGpioDOutputRegister->odr_1 = 0;

		CheckRow(1);

		pGpioDOutputRegister->odr_1 = 1;
		pGpioDOutputRegister->odr_2 = 0;

		CheckRow(2);

		pGpioDOutputRegister->odr_2 = 1;
		pGpioDOutputRegister->odr_3 = 0;

		CheckRow(3);

		pGpioDOutputRegister->odr_3 = 1;
	}

    /* Loop forever */
	for(;;);
}

void Inintialize()
{
	pRCCRegister->gpioD_en = 1;

	pGpioDModeRegister->moder_8 = 0;
	pGpioDModeRegister->moder_9 = 0;
	pGpioDModeRegister->moder_10 = 0;
	pGpioDModeRegister->moder_11 = 0;

	pGpioDPullRegister->moder_8 = 1;
	pGpioDPullRegister->moder_9 = 1;
	pGpioDPullRegister->moder_10 = 1;
	pGpioDPullRegister->moder_11 = 1;

	pGpioDModeRegister->moder_0 = 1;
	pGpioDModeRegister->moder_1 = 1;
	pGpioDModeRegister->moder_2 = 1;
	pGpioDModeRegister->moder_3 = 1;

	pGpioDOutputRegister->odr_0 = 1;
	pGpioDOutputRegister->odr_1 = 1;
	pGpioDOutputRegister->odr_2 = 1;
	pGpioDOutputRegister->odr_3 = 1;
}

void CheckRow(int row)
{
	if(pGpioDInputRegister->odr_8 == 0)
	{
		DelayDevice();

		switch(row)
		{
			case 0:
				printf("Button 1 pressed!\n");
				break;
			case 1:
				printf("Button 2 pressed!\n");
				break;
			case 2:
				printf("Button 3 pressed!\n");
				break;
			case 3:
				printf("Button A pressed!\n");
				break;
		}
	}
	else if(pGpioDInputRegister->odr_9 == 0)
	{
		DelayDevice();

		switch(row)
		{
			case 0:
				printf("Button 4 pressed!\n");
				break;
			case 1:
				printf("Button 5 pressed!\n");
				break;
			case 2:
				printf("Button 6 pressed!\n");
				break;
			case 3:
				printf("Button B pressed!\n");
				break;
		}
	}
	else if(pGpioDInputRegister->odr_10 == 0)
	{
		DelayDevice();

		switch(row)
		{
			case 0:
				printf("Button 7 pressed!\n");
				break;
			case 1:
				printf("Button 8 pressed!\n");
				break;
			case 2:
				printf("Button 9 pressed!\n");
				break;
			case 3:
				printf("Button C pressed!\n");
				break;
		}
	}
	else if(pGpioDInputRegister->odr_11 == 0)
	{
		DelayDevice();
		switch(row)
		{
			case 0:
				printf("Button * pressed!\n");
				break;
			case 1:
				printf("Button 0 pressed!\n");
				break;
			case 2:
				printf("Button # pressed!\n");
				break;
			case 3:
				printf("Button D pressed!\n");
				break;
		}
	}
}

void DelayDevice()
{
	for(int volatile i = 0; i <= 1000000; i++);
}
